from collections import deque

class MyStack:
    def __init__(self):
        self.q1 = deque()
        self.q2 = deque()

    def push(self, x: int) -> None:
        # Push x first in empty q2
        self.q2.append(x)

        # Push all the remaining elements in q1 to q2.
        while len(self.q1) != 0:
            self.q2.append(self.q1[0])
            self.q1.popleft()

        # swap the names of two queues
        self.q1, self.q2 = self.q2, self.q1

    def pop(self) -> int:
        # if no elements are there in q1
        if len(self.q1) == 0:
            return

        self.q1.popleft()

    def top(self) -> int:
        if len(self.q1) == 0:
            return -1
        return self.q1[0]

    def empty(self) -> bool:
        return len(self.q1) == 0

    def size(self) -> int:
        return len(self.q1)
